select (select count(*) from case_decoy_categories where location_id = 'ee497c59-0b63-50e6-91fc-8c67893c99ed') decoys, (select location_id is null from evidence where name like 'Журнал вахтёрши%' and case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab') journal_from_person, (select count(*) from characters where name like 'Роза-апа%') roza;
